INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200001, now(), now(), 'seed', '<h2>خطط التمويل</h2><p>نعمل مع البنك الأهلي المصري وبنك مصر وشركة كونتكت للتمويل. المقدم يبدأ من 20% من قيمة السيارة، ومدة التقسيط تصل إلى ستين شهرًا.</p><ul><li>مقدم 20% — قسط 60 شهرًا</li><li>مقدم 35% — قسط 48 شهرًا بفائدة أقل</li><li>مقدم 50% — قسط 36 شهرًا</li></ul><h2>المستندات المطلوبة</h2><ul><li>صورة بطاقة الرقم القومي سارية</li><li>مفردات مرتب حديثة أو سجل تجاري وبطاقة ضريبية</li><li>كشف حساب بنكي لآخر ستة أشهر</li></ul><p>الموافقة المبدئية تصدر خلال 48 ساعة عمل، والتسليم بعد استكمال الترخيص.</p>', 'التمويل والتقسيط', 'التمويل والتقسيط', 'خطط تقسيط حتى 60 شهرًا بالتعاون مع البنك الأهلي وبنك مصر، مع حاسبة أقساط تقريبية.', 'تمويل, تقسيط, أقساط سيارات', 'التمويل والتقسيط | Egypt Car Sales', 'financing-ar', 'ar', -20001, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200002, now(), now(), 'seed', '<h2>Nos plans de financement</h2><p>Nous travaillons avec la Banque Nationale d''Égypte, Banque Misr et Contact Financial. L''apport démarre à 20 % du prix du véhicule, sur une durée pouvant aller jusqu''à soixante mois.</p><ul><li>Apport 20 % — 60 mensualités</li><li>Apport 35 % — 48 mensualités, taux réduit</li><li>Apport 50 % — 36 mensualités</li></ul><h2>Pièces à fournir</h2><ul><li>Carte nationale d''identité en cours de validité</li><li>Bulletins de salaire récents, ou registre de commerce et carte fiscale</li><li>Relevés bancaires des six derniers mois</li></ul><p>L''accord de principe est rendu sous 48 heures ouvrées ; la livraison suit l''immatriculation.</p>', 'Financement', 'Financement', 'Des plans de financement jusqu''à 60 mois avec la Banque Nationale d''Égypte et Banque Misr.', 'financement, crédit auto, mensualités', 'Financement | Egypt Car Sales', 'financement', 'fr', -20001, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

-- page: inspection-report (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-20002, now(), now(), 'seed', 'inspection-report', 'PAGE', 11, true, '65f023632bc26470c104b75f', 'PUBLISHED', null, null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, null)
