INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200003, now(), now(), 'seed', '<h2>لماذا 150 نقطة؟</h2><p>لأن ما لا يُقاس لا يُباع بثقة. كل سيارة مستعملة تدخل معرضنا تمر على ورشة الفحص في المعادي قبل أن تُعرض.</p><h3>ما يشمله الفحص</h3><ul><li>المحرك وناقل الحركة: ضغط الاسطوانات، تسريبات، حالة الزيوت</li><li>الهيكل: قياس سماكة الطلاء في 18 موضعًا لكشف الإصلاحات</li><li>نظام الفرامل والتعليق والإطارات</li><li>الكهرباء وأنظمة الأمان والوسائد الهوائية</li><li>قراءة كمبيوتر السيارة وسجل الأعطال المخزّنة</li></ul><h3>التقرير</h3><p>يُسلَّم التقرير كاملًا قبل التوقيع، بما فيه الملاحظات السلبية. السيارة التي ترسب في بند سلامة لا تُعرض أصلًا.</p>', 'تقرير الفحص الـ 150 نقطة', 'تقرير الفحص الـ 150 نقطة', 'كل سيارة مستعملة تمر بفحص من 150 نقطة قبل عرضها، والتقرير متاح لك قبل الشراء.', 'فحص سيارات, سيارات مستعملة, تقرير فني', 'تقرير الفحص | Egypt Car Sales', 'inspection-report-ar', 'ar', -20002, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200004, now(), now(), 'seed', '<h2>Pourquoi 150 points ?</h2><p>Parce qu''on ne vend pas en confiance ce qu''on n''a pas mesuré. Chaque véhicule d''occasion passe par l''atelier de Maadi avant d''être exposé.</p><h3>Ce que couvre l''inspection</h3><ul><li>Moteur et boîte : compression, fuites, état des huiles</li><li>Carrosserie : épaisseur de peinture relevée en 18 points pour détecter les reprises</li><li>Freinage, suspension et pneumatiques</li><li>Électricité, équipements de sécurité et airbags</li><li>Lecture du calculateur et des défauts mémorisés</li></ul><h3>Le rapport</h3><p>Il est remis intégralement avant signature, remarques négatives comprises. Un véhicule recalé sur un point de sécurité n''est pas mis en vente.</p>', 'Le rapport d''inspection en 150 points', 'Le rapport d''inspection en 150 points', 'Chaque véhicule d''occasion passe une inspection en 150 points ; le rapport vous est remis avant l''achat.', 'inspection, occasion, rapport technique', 'Rapport d''inspection | Egypt Car Sales', 'rapport-inspection', 'fr', -20002, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

