INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200005, now(), now(), 'seed', '<h2>كيف يعمل الاستبدال</h2><ol><li>احجز موعد تقييم مجاني في فرع مدينة نصر أو المعادي</li><li>الفحص يستغرق ساعة، والعرض ساري لسبعة أيام</li><li>إن قبلت، نخصم القيمة مباشرة من السيارة الجديدة</li></ol><h2>ما يرفع قيمة سيارتك</h2><ul><li>سجل صيانة كامل من مركز معتمد</li><li>عدد كيلومترات منطقي بالنسبة لسنة الصنع</li><li>هيكل خالٍ من إصلاحات الحوادث</li></ul><p>نتولى إجراءات نقل الملكية بالكامل، بما فيها المرور.</p>', 'استبدال سيارتك', 'استبدال سيارتك', 'قيّم سيارتك القديمة واخصم قيمتها من سيارتك الجديدة في نفس اليوم.', 'استبدال, تقييم سيارات, بيع سيارتك', 'استبدال سيارتك | Egypt Car Sales', 'trade-in-ar', 'ar', -20003, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200006, now(), now(), 'seed', '<h2>Comment se passe une reprise</h2><ol><li>Prenez rendez-vous pour une estimation gratuite à Nasr City ou à Maadi</li><li>L''expertise dure une heure ; l''offre reste valable sept jours</li><li>Si vous l''acceptez, la valeur est déduite du prix de votre nouvelle voiture</li></ol><h2>Ce qui fait monter l''estimation</h2><ul><li>Un carnet d''entretien complet dans un centre agréé</li><li>Un kilométrage cohérent avec l''année</li><li>Une carrosserie sans reprise accidentelle</li></ul><p>Nous prenons en charge la totalité du transfert de propriété, formalités administratives comprises.</p>', 'Reprise de votre véhicule', 'Reprise de votre véhicule', 'Faites évaluer votre véhicule et déduisez sa valeur de votre prochaine voiture, le jour même.', 'reprise, estimation, revendre sa voiture', 'Reprise | Egypt Car Sales', 'reprise', 'fr', -20003, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

