INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200007, now(), now(), 'seed', '<h2>فروعنا</h2><p>هذه الصفحة تابعة لصفحة « موقعنا »، وتستخدم أيضًا للتحقق من مسار التنقل: الرئيسية › موقعنا › فروعنا.</p><ul><li><strong>مدينة نصر</strong> — 123 شارع أوتو رود — يوميًا 10ص إلى 9م</li><li><strong>المعادي</strong> — ورشة الفحص ومركز الخدمة — السبت إلى الخميس 9ص إلى 6م</li><li><strong>الشيخ زايد</strong> — معرض السيارات الكهربائية — يوميًا 11ص إلى 10م</li></ul>', 'فروعنا', 'فروعنا', 'ثلاثة معارض في القاهرة الكبرى: مدينة نصر، المعادي، والشيخ زايد.', 'فروع, معارض سيارات, القاهرة', 'فروعنا | Egypt Car Sales', 'showrooms-ar', 'ar', -20004, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200008, now(), now(), 'seed', '<h2>Nos showrooms</h2><p>Cette page est rattachée à « Notre emplacement », ce qui en fait aussi le contrôle du fil d''Ariane : Accueil › Notre emplacement › Nos showrooms.</p><ul><li><strong>Nasr City</strong> — 123 Auto Road — tous les jours, 10h–21h</li><li><strong>Maadi</strong> — atelier d''inspection et service — samedi au jeudi, 9h–18h</li><li><strong>Sheikh Zayed</strong> — showroom véhicules électriques — tous les jours, 11h–22h</li></ul>', 'Nos showrooms', 'Nos showrooms', 'Trois showrooms au Grand Caire : Nasr City, Maadi et Sheikh Zayed.', 'showroom, concession, Le Caire', 'Nos showrooms | Egypt Car Sales', 'showrooms', 'fr', -20004, 'TRANSLATED', null, null, null, null)
