INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200009, now(), now(), 'seed', '<h2>الشاحن المنزلي</h2><p>مع كل سيارة كهربائية نركّب شاحنًا منزليًا 7 كيلوواط مجانًا داخل القاهرة الكبرى، ويشمل ذلك الكابل ولوحة الحماية.</p><h2>الشحن على الطريق</h2><p>شبكة الشحن السريع في مصر تجاوزت 320 نقطة، أغلبها على محاور القاهرة–الإسكندرية والقاهرة–العين السخنة.</p><ul><li>شحن منزلي 7 كيلوواط: من 20% إلى 80% في نحو ست ساعات</li><li>شحن سريع 60 كيلوواط: نفس المدى في أربعين دقيقة تقريبًا</li></ul><p>هذه الصفحة تحمل رابطًا قانونيًا وصورة Open Graph للتحقق من بيانات الـ SEO في المتجر.</p>', 'شحن السيارات الكهربائية', 'شحن السيارات الكهربائية', 'شاحن منزلي مركّب مجانًا مع كل سيارة كهربائية، وخريطة نقاط الشحن في مصر.', 'شحن كهربائي, سيارات كهربائية, شاحن منزلي', 'شحن السيارات الكهربائية | Egypt Car Sales', 'ev-charging-ar', 'ar', -20005, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-200010, now(), now(), 'seed', '<h2>La borne domestique</h2><p>Chaque véhicule électrique est livré avec une borne domestique de 7 kW installée gratuitement dans le Grand Caire, câble et tableau de protection compris.</p><h2>Recharger sur la route</h2><p>Le réseau de charge rapide égyptien dépasse 320 points, concentrés sur les axes Le Caire–Alexandrie et Le Caire–Aïn Sokhna.</p><ul><li>Borne domestique 7 kW : de 20 % à 80 % en six heures environ</li><li>Charge rapide 60 kW : la même plage en une quarantaine de minutes</li></ul><p>Cette page porte une URL canonique et une image Open Graph, ce qui en fait le contrôle du rendu SEO.</p>', 'Recharge des véhicules électriques', 'Recharge des véhicules électriques', 'Borne domestique installée gratuitement avec chaque véhicule électrique, et la carte des points de charge en Égypte.', 'recharge, véhicule électrique, borne domestique', 'Recharge électrique | Egypt Car Sales', 'recharge-electrique', 'fr', -20005, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

