VALUES (-200011, now(), now(), 'seed', '<h2>عروض الشركات</h2><p>هذه الصفحة مُعلَّمة بـ <code>noindex</code>: يجب أن تظهر داخل المتجر لكن تختفي من خريطة الموقع. هذا هو اختبار العلامة.</p><ul><li>خصم يبدأ من خمس سيارات</li><li>عقود صيانة ثلاث سنوات</li><li>سيارة بديلة أثناء الصيانة</li></ul>', 'مبيعات الأساطيل', 'مبيعات الأساطيل', 'صفحة موجّهة لعملاء الشركات، ومستبعدة عمدًا من الفهرسة.', 'أساطيل, شركات, عقود', 'مبيعات الأساطيل | Egypt Car Sales', 'fleet-sales-ar', 'ar', -20006, 'TRANSLATED', null, null, null, null)
