VALUES (-200012, now(), now(), 'seed', '<h2>Offres entreprises</h2><p>Cette page est marquée <code>noindex</code> : elle doit s''afficher dans la boutique mais disparaître du sitemap. C''est le contrôle du drapeau.</p><ul><li>Remise à partir de cinq véhicules</li><li>Contrats d''entretien sur trois ans</li><li>Véhicule de remplacement pendant les immobilisations</li></ul>', 'Ventes aux flottes', 'Ventes aux flottes', 'Une page destinée aux clients entreprises, volontairement exclue de l''indexation.', 'flotte, entreprise, contrat', 'Ventes aux flottes | Egypt Car Sales', 'ventes-flottes', 'fr', -20006, 'TRANSLATED', null, null, null, null)
