VALUES (-200013, now(), now(), 'seed', '<h2>عروض الصيف</h2><p>هذه الصفحة بحالة <strong>SCHEDULED</strong> وتُنشر بعد ثلاثة أسابيع. يجب أن تظهر في لوحة التحكم وتعطي 404 في المتجر.</p>', 'عروض الصيف (مجدولة)', 'عروض الصيف (مجدولة)', 'صفحة مجدولة: يجب ألا تظهر في المتجر قبل موعد نشرها.', 'عروض, صيف', 'عروض الصيف | Egypt Car Sales', 'summer-offers-ar', 'ar', -20007, 'TRANSLATED', null, null, null, null)
